72	static inline uint32_t rgb565_to_argb8888(uint16_t c)
73	{
74	  uint32_t r = (c >> 11) & 0x1F;
75	  uint32_t g = (c >> 5) & 0x3F;
76	  uint32_t b = c & 0x1F;
77	
